{
  "platform": "host",
  "provider": "Service",
  "method": "listService",
  "data": {
    "mode": "service",
    "service": {
      "key": "storageDomain",
      "description": "The mounted domain facility. Opens declared domains over routed backends; one facility instance owns the open-domain table and enforces single-open per domain name. Handles serve cached reads and updates. Shared-state decisions use table.modify with an atomic backend; its callbacks must be synchronous, pure and must not call storage.",
      "access": {
        "optional": {
          "expression": "ctx.get(\"storageDomain\")",
          "requiresUndefinedCheck": true
        },
        "hardDependency": {
          "inject": [
            "storageDomain"
          ],
          "expression": "ctx.storageDomain"
        }
      },
      "methods": [
        {
          "signature": "async open<S extends DomainSpec>(spec: S): Promise<Domain<S>>",
          "description": "Open one declared domain. Steps, each failing the whole call: reject a name that is already open (`already-open`); resolve the backend route (`backend-not-found` passes through from the hub); require its `kv` facet (`facet-unsupported`); open the unit projected from the spec (backend `version-mismatch`/`malformed-medium` pass through); load and validate every stored record against the spec's zod schemas (`invalid-record` with the offending table and key — unless the spec declares `invalidRecords: 'backup-and-skip'` and the unit can move documents aside, in which case the failing record is backed up, logged, and skipped); construct the domain.\n\nLifecycle: the CALLER owns the returned handle and closes it via `Domain.close()` (typically as its own `ctx.effect` disposer) — the facility does not tie the domain to any consumer fiber. Domains still open when the facility unmounts are closed by the plugin disposer.",
          "parameters": [
            {
              "name": "spec",
              "description": "The domain declaration, typically from `defineDomain`."
            }
          ],
          "returns": "the opened domain handle, typed by the spec."
        },
        {
          "signature": "get(name: string): DomainImpl | undefined",
          "description": "Look up an open domain by name, untyped. Diagnostic surface (the package invariant cross-checks change events against live domain state); typed consumers hold the handle returned by open.",
          "parameters": [
            {
              "name": "name",
              "description": "Domain name."
            }
          ],
          "returns": "the open domain runtime, or `undefined` when not open."
        },
        {
          "signature": "async closeAll(): Promise<void>",
          "description": "Close every domain still open on this facility. The unmount path for consumers that never called `Domain.close()` themselves; closing is idempotent, so double-closing an already-closed domain is harmless.",
          "parameters": [],
          "returns": "resolution after every unit is released."
        }
      ]
    },
    "referencedTypes": [
      {
        "name": "Domain",
        "declaration": "export interface Domain<S extends DomainSpec> {\n    readonly name: string;\n    readonly global: DomainGlobalHandleOf<S>;\n    table<N extends keyof S['tables'] & string>(name: N): KvTable<TableKeyOf<S, N>, TableValueOf<S, N>>;\n    close(): Promise<void>;\n}"
      },
      {
        "name": "DomainGlobal",
        "declaration": "export interface DomainGlobal<G> {\n    get(): G;\n    set(value: G): Promise<void>;\n}"
      },
      {
        "name": "DomainGlobalHandleOf",
        "declaration": "export type DomainGlobalHandleOf<S extends DomainSpec> = S extends {\n    readonly global: DomainGlobalSpec<infer G>;\n} ? DomainGlobal<G> : never;"
      },
      {
        "name": "DomainGlobalSpec",
        "declaration": "export interface DomainGlobalSpec<G> {\n    readonly schema: ZodType<G>;\n    readonly initial: G;\n}"
      },
      {
        "name": "DomainImpl",
        "declaration": "export class DomainImpl {\n    readonly name: string;\n    constructor(private readonly ctx: Context, spec: DomainSpec, private readonly unit: KvUnit, records: Map<string, DomainTableData>, globalValue: unknown, private readonly onClosed: () => void);\n    get global(): DomainGlobal<unknown>;\n    table(name: string): KvTable<string, unknown>;\n    close(): Promise<void>;\n}"
      },
      {
        "name": "DomainSpec",
        "declaration": "export interface DomainSpec {\n    readonly name: string;\n    readonly version: number;\n    readonly layout?: 'single' | 'per-record';\n    readonly compatibleVersions?: readonly number[];\n    readonly invalidRecords?: 'backup-and-skip';\n    readonly global?: DomainGlobalSpec<unknown>;\n    readonly tables: Record<string, DomainTableSpec>;\n}"
      },
      {
        "name": "DomainTableData",
        "declaration": "export interface DomainTableData {\n    readonly records: Map<string, unknown>;\n    readonly valueSchema: ZodType;\n}"
      },
      {
        "name": "DomainTableSpec",
        "declaration": "export interface DomainTableSpec<K extends string = string, V = unknown> {\n    readonly valueSchema: ZodType<V>;\n    readonly __key?: K;\n}"
      },
      {
        "name": "KvTable",
        "declaration": "export interface KvTable<K extends string, V> {\n    get(key: K): V | undefined;\n    entries(): IterableIterator<[\n        K,\n        V\n    ]>;\n    keys(): IterableIterator<K>;\n    readonly size: number;\n    put(key: K, value: V): Promise<void>;\n    delete(key: K): Promise<boolean>;\n    update(key: K, fn: (current: V) => V): Promise<V>;\n    modify(key: K, fn: (current: V | undefined) => V | undefined): Promise<V | undefined>;\n}"
      },
      {
        "name": "KvUnit",
        "declaration": "export interface KvUnit {\n    loadAll(): Promise<{\n        tables: Record<string, Record<string, unknown>>;\n        global: unknown;\n    }>;\n    putRecord(table: string, key: string, value: unknown): Promise<void>;\n    modifyRecord?(table: string, key: string, modify: (current: unknown) => unknown): Promise<unknown>;\n    deleteRecord(table: string, key: string): Promise<void>;\n    backupRecord?(table: string, key: string): Promise<string>;\n    setGlobal(value: unknown): Promise<void>;\n    close(): Promise<void>;\n}"
      },
      {
        "name": "TableKeyOf",
        "declaration": "export type TableKeyOf<S extends DomainSpec, N extends keyof S['tables']> = S['tables'][N] extends DomainTableSpec<infer K> ? K : never;"
      },
      {
        "name": "TableValueOf",
        "declaration": "export type TableValueOf<S extends DomainSpec, N extends keyof S['tables']> = S['tables'][N] extends DomainTableSpec<string, infer V> ? V : never;"
      }
    ]
  }
}
